def cumulative_counts(items):
    counts = {}
    result = []
    for it in items:
        counts[it] = counts.get(it, 0) + 1
        result.append(counts[it])
    return result

def count_char_categories(s):
    d = {'digits': 0, 'letters': 0, 'spaces': 0, 'other': 0}
    for c in s:
        if c.isdigit():
            d['digits'] += 1
        elif c.isalpha():
            d['letters'] += 1
        elif c.isspace():
            d['spaces'] += 1
        else:
            d['other'] += 1
    return d

def word_length_distribution(text):
    words = text.split()
    d = {}
    for w in words:
        d[len(w)] = d.get(len(w), 0) + 1
    return d

def rank_items_by_frequency(items):
    counts = {}
    for it in items:
        counts[it] = counts.get(it, 0) + 1
    sorted_vals = sorted(counts.items(), key=lambda x: (-x[1], x[0]))
    result = {}
    for i, (val, cnt) in enumerate(sorted_vals):
        result[val] = i + 1
    return result

def flatten_and_count(nested):
    d = {}
    def flatten(lst):
        for item in lst:
            if isinstance(item, list):
                flatten(item)
            else:
                d[item] = d.get(item, 0) + 1
    flatten(nested)
    return d

def count_common_elements(list1, list2):
    c1 = {}
    for x in list1:
        c1[x] = c1.get(x, 0) + 1
    c2 = {}
    for x in list2:
        c2[x] = c2.get(x, 0) + 1
    result = {}
    for k in c1:
        if k in c2:
            result[k] = min(c1[k], c2[k])
    return result

def count_keys_by_value_parity(d):
    even = 0
    odd = 0
    for v in d.values():
        if v % 2 == 0:
            even += 1
        else:
            odd += 1
    return {'even': even, 'odd': odd}

def group_evens_odds_sum(nums):
    even_sum = 0
    odd_sum = 0
    for n in nums:
        if n % 2 == 0:
            even_sum += n
        else:
            odd_sum += n
    return {'even': even_sum, 'odd': odd_sum}

def merge_dict_lists_unique(d1, d2):
    result = {}
    keys = set(d1.keys()) | set(d2.keys())
    for k in keys:
        vals = set()
        if k in d1:
            vals.update(d1[k])
        if k in d2:
            vals.update(d2[k])
        result[k] = sorted(vals)
    return result

def build_index_map(words):
    d = {}
    for i, w in enumerate(words):
        d.setdefault(w, []).append(i)
    return d

def most_common_n_chars(s, n):
    counts = {}
    for c in s:
        counts[c] = counts.get(c, 0) + 1
    sorted_chars = sorted(counts.items(), key=lambda x: (-x[1], x[0]))
    return sorted_chars[:n]

def dict_average_values(list_of_dicts):
    sums = {}
    counts = {}
    for d in list_of_dicts:
        for k, v in d.items():
            sums[k] = sums.get(k, 0) + v
            counts[k] = counts.get(k, 0) + 1
    return {k: sums[k] / counts[k] for k in sums}

def count_letters_ignore_case(s):
    d = {}
    for c in s:
        if c.isalpha():
            lc = c.lower()
            d[lc] = d.get(lc, 0) + 1
    return d

def group_by_digit_count(nums):
    d = {}
    for n in nums:
        digit_count = len(str(abs(n)))
        d.setdefault(digit_count, []).append(n)
    for k in d:
        d[k].sort()
    return d

def tally_votes(votes):
    d = {}
    for v in votes:
        d[v] = d.get(v, 0) + 1
    return d

def count_bigrams(text):
    words = text.split()
    d = {}
    for i in range(len(words) - 1):
        key = words[i] + ' ' + words[i + 1]
        d[key] = d.get(key, 0) + 1
    return d

def common_keys_with_equal_values(d1, d2):
    result = []
    for k in d1:
        if k in d2 and d1[k] == d2[k]:
            result.append(k)
    return sorted(result)

def dict_difference_values(d1, d2):
    result = {}
    for k in d1:
        if k in d2:
            result[k] = d1[k] - d2[k]
    return result
